import{_ as e,r as a,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"重定向 - October CMS - 3.x","titleTemplate":false,"description":"了解如何重定向到另一个页面或 URL。","frontmatter":{"subtitle":"了解如何重定向到另一个页面或 URL。"},"headers":[{"level":2,"title":"重定向到 CMS 页面","slug":"重定向到-cms-页面","link":"#重定向到-cms-页面","children":[]},{"level":2,"title":"在 Twig 中重定向","slug":"在-twig-中重定向","link":"#在-twig-中重定向","children":[]},{"level":2,"title":"在 AJAX 中重定向","slug":"在-ajax-中重定向","link":"#在-ajax-中重定向","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/cms/features/redirects.md","filePath":"3.x/zh-cn/cms/features/redirects.md"}'),i={name:"3.x/zh-cn/cms/features/redirects.md"};function r(k,n,g,d,m,h){const t=a("pre-heading"),p=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"重定向",-1)),s(p),n[1]||(n[1]=u(`<p>在某些情况下，你可能希望在提交表单或任何 AJAX 请求后将用户重定向到新页面。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSignup<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Email<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>email<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Sign Up
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>在你的 <a href="./../ajax/handlers.html">AJAX 处理程序</a> 中，你可以返回一个 <code>Redirect</code> <a href="./../../extend/services/response-view.html">响应类型</a>，其中 <code>to</code> 方法接受相对或绝对 URL（第一个参数）。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSignup</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/signup-complete&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>你可以使用 <code>refresh</code> 方法刷新当前页面。同时也支持使用<a href="./flash-messages.html">闪存消息</a>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSignup</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Signup complete!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">refresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="重定向到-cms-页面"><a href="#重定向到-cms-页面" class="header-anchor">#</a> 重定向到 CMS 页面</h2><p><code>Cms</code> 门面和 <code>redirect</code> 方法可用于重定向到特定的 CMS 页面（第一个参数）以及任何可选的路由参数（第二个参数）。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRedirect</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Cms</span><span class="token operator">::</span><span class="token function">redirect</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blog/post&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;foobar&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>你可以使用 <code>pageUrl</code> 方法将 URL 作为字符串返回。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$postPage</span> <span class="token operator">=</span> <span class="token class-name static-context">Cms</span><span class="token operator">::</span><span class="token function">pageUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blog/post&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;foobar&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="在-twig-中重定向"><a href="#在-twig-中重定向" class="header-anchor">#</a> 在 Twig 中重定向</h2><p><a href="./../../markup/function/redirect.html"><code>redirect()</code> Twig 函数</a>可用于从页面标记中重定向用户。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSignup</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;success&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>此函数接受 URL 或 CMS 页面名称。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> success <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> redirect<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>/signup-complete<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="在-ajax-中重定向"><a href="#在-ajax-中重定向" class="header-anchor">#</a> 在 AJAX 中重定向</h2><p><a href="./../ajax/introduction.html">AJAX 框架</a>通过 <code>data-request-redirect</code> 属性支持重定向。属性值应指定在成功的 AJAX 请求完成后要重定向到的 URL 位置。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-redirect</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/signup-complete<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Save and Redirect
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a href="./../ajax/turbo-router.html">turbo 路由器</a>通过 <code>data-browser-redirect-back</code> 属性支持历史重定向。该属性可以附加到任何超链接或 AJAX 请求元素上，覆盖重定向响应，并且仅在存在先前的浏览器历史状态时触发。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRedirect<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-browser-redirect-back</span><span class="token punctuation">&gt;</span></span>
    Save and Back
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>该属性值也可以用于超链接。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/home<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-browser-redirect-back</span><span class="token punctuation">&gt;</span></span>
    Go Back
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block warning"><p><code>data-browser-redirect-back</code> 属性应与传统重定向结合使用，作为备用位置。</p></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../markup/function/redirect.html">重定向 Twig 函数</a></li><li><a href="./../../extend/services/response-view.html">响应和视图</a></li></ul></div>`,26))])}const w=e(i,[["render",r]]);export{v as __pageData,w as default};
